import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 81 · Everyday recipe: old-fashioned beef stew

sc("""Sweetheart, a good beef stew should have meat so tender you can cut it with a spoon, a gravy thick and dark and shiny, and potatoes that hold their shape. But most stews I taste today are gray, watery, and full of tough little cubes of beef like pencil erasers. And it's not the recipe. It's five little mistakes that almost everybody makes, and every one of them is easy to fix.""",
   "watery gray beef stew in bowl", "LIKE PENCIL ERASERS")
sc("""So tonight I'm giving you my mother's Sunday beef stew, step by step, the way she made it every cold Sunday on Elm Street. And stay with me, because the last secret is something she did in the last ten minutes, with one ingredient you already have in your kitchen, and it makes the gravy taste like it simmered for two days.""",
   "rich dark beef stew in dutch oven", "THE LAST TEN MINUTES")

ch("Sunday stew")
sc("""In our house, beef stew was for the coldest Sundays, after church, when the wind was blowing snow sideways down Elm Street. My mother started it before we left for the service, in a big black iron pot on the back of the stove, and when we came home, the whole house smelled so good that Danny would run up the porch steps and burn his tongue on the first spoonful.""",
   "family coming home from church in snow 1950s", "AFTER CHURCH")
sc("""Stew was a poor family's best friend, honey. It took the cheapest, toughest cut of beef in the butcher's case and turned it into something you'd serve the minister. One pound of chuck, a few potatoes, a couple of carrots and an onion, and you could feed six people for less than a dollar in nineteen fifty-five. In a minute I'll tell you why the cheap cut is actually better.""",
   "1950s butcher case beef chuck", "THE CHEAPEST CUT")
sc("""My father ate three bowls, every time, with my mother's buttermilk biscuits. And he always said the same thing. Dorothy, this is better than the last one. And my mother always said, Walter, it's the same stew. And he said, then I'm getting hungrier. They had that same conversation every winter Sunday for forty years.""",
   "man eating stew with biscuits", "BETTER THAN THE LAST ONE")

ch("What you need")
sc("""Here's what you need for six people. Two and a half pounds of beef chuck roast. Two tablespoons of flour, salt and pepper. Three tablespoons of oil or bacon grease. One big onion, three cloves of garlic, two tablespoons of tomato paste. Four cups of beef broth. A bay leaf and some thyme. A pound and a half of small potatoes, four carrots, and two stalks of celery.""",
   "beef chuck potatoes carrots onions", "THE INGREDIENTS")
sc("""And here's mistake number one. Buying the little package labeled stew meat. It's scraps from all different cuts, some lean, some tough, and they cook at different speeds, so half of it's dry and half of it's chewy. Buy a whole chuck roast and cut it yourself into big chunks, about two inches. Chuck has fat and connective tissue running through it, and after a long slow cook, that melts into the gravy.""",
   "cutting chuck roast into big cubes", "BUY A CHUCK ROAST")
sc("""Big chunks, honey. Not little ones. Little cubes dry out before they get tender. Two-inch chunks stay juicy inside. My mother cut them so big that Danny once asked if we were having pot roast. She said, it's stew if it's in gravy, and pot roast if it's on a platter. Same meat.""",
   "large beef chunks on cutting board", "TWO-INCH CHUNKS")

ch("Browning")
sc("""Pat the beef dry with paper towels. That's important. Then season it with salt and pepper, and toss it in the flour. Heat the oil in a heavy pot over medium-high heat until it shimmers. And here's mistake number two. Crowding the pot. If you dump all the meat in at once, it steams instead of browning, and it turns gray. Brown it in three batches, with space between the pieces.""",
   "browning beef chunks in dutch oven", "DON'T CROWD THE POT")
sc("""Leave each piece alone until it has a dark brown crust on the bottom, about three minutes, then turn it. Don't keep poking at it. That dark crust is where all the flavor of a stew comes from. Put each batch on a plate as it's done. And don't you dare wash out that pot, sweetheart. Those brown bits stuck to the bottom are gold.""",
   "brown crust on seared beef", "THE BROWN BITS ARE GOLD")
sc("""If this is helping you, tap the like button for me, honey. It helps Grandma more than you know. Now turn the heat down to medium, and add the chopped onion to the same pot. Stir it around, scraping up those brown bits, for about five minutes, until it's soft. Add the garlic and the tomato paste, and cook it for two more minutes, until the paste turns a darker brick red.""",
   "onions and tomato paste in pot", "BRICK RED")

ch("Simmering")
sc("""Pour in a splash of the broth and scrape the bottom of the pot with a wooden spoon until it's clean. Then add the rest of the broth, the bay leaf and the thyme, and put the beef back in, with all the juice from the plate. Bring it just to a boil, then turn it down as low as it will go, put the lid on, and let it barely bubble.""",
   "stew simmering in covered pot", "BARELY BUBBLING")
sc("""And mistake number three. Boiling it hard. A hard boil makes the meat seize up and turn stringy and tough, no matter how long you cook it. You want a lazy little bubble, just breaking the surface now and then. Or put the covered pot in a three hundred twenty-five degree oven, which is what I do now. It cooks gently on all sides, and you can't burn the bottom.""",
   "dutch oven in oven", "NEVER A HARD BOIL")
sc("""Let it go for an hour and a half. Then comes mistake number four. Putting the vegetables in at the beginning. If the potatoes and carrots cook for three hours, they turn to mush and disappear into the gravy. Add them after an hour and a half, cut into big pieces, and give it another hour, until a fork slides through the beef and the potatoes are just tender.""",
   "adding potatoes and carrots to stew", "VEGETABLES GO IN LATER")
sc("""How do you know the beef is done? Take out one piece and press it with a spoon. If it falls apart, it's ready. If it fights back, give it another half hour. It's not a matter of time, honey, it's a matter of tenderness. Every piece of beef is different, and the pot will tell you when it's done, if you listen.""",
   "beef falling apart with spoon", "PRESS IT WITH A SPOON")

ch("The secret")
sc("""Now the secret I promised you, the last ten minutes. Mistake number five is a flat, dull gravy that tastes like nothing but salt. My mother fixed it with one ingredient. A splash of vinegar. One tablespoon of plain cider vinegar or red wine vinegar, stirred in right at the end. Taste it before and after. It wakes up the whole pot like turning on a light.""",
   "splash of vinegar into stew pot", "A SPLASH OF VINEGAR")
sc("""Vinegar doesn't make it taste sour, sweetheart. It cuts through the richness and makes the beef taste beefier and the gravy taste deeper. Good chefs do the same thing with a squeeze of lemon. And if your gravy is too thin, mash two or three of the potatoes against the side of the pot and stir them in. They thicken it naturally, with no lumpy flour.""",
   "mashing potato against pot side", "WAKE IT UP")
sc("""And finish it with a handful of frozen peas and some chopped fresh parsley, stirred in right before you serve it. The peas only need two minutes in the hot stew. They add a little sweetness and a pop of bright green, and the parsley makes it look like a picture in a magazine. My mother grew her parsley in a coffee can on the kitchen windowsill all winter long.""",
   "peas and parsley on beef stew", "A POP OF GREEN")

sc("""And if you want a little extra flavor, honey, here are my grown-up tricks. Replace one cup of the broth with a cup of red wine or a dark beer, poured in when you scrape the pot. Or add a spoonful of Worcestershire sauce with the broth. My husband liked a few mushrooms browned in butter and stirred in at the end. Whatever you add, add it one at a time, and taste.""",
   "red wine bottle and mushrooms kitchen", "GROWN-UP TRICKS")
ch("Serving it")
sc("""Serve it in deep bowls, with buttermilk biscuits or a thick slice of bread for mopping up the gravy. And here's the truth about beef stew, honey. It's even better the next day. Let it cool, put it in the icebox overnight, and the flavors marry. You can lift the hardened fat off the top in the morning, too. I always make it on Saturday for Sunday.""",
   "beef stew bowl with biscuit", "BETTER THE NEXT DAY")
sc("""It freezes beautifully for three months, sweetheart. Freeze it in quart containers, and on a busy weeknight, you've got a dinner that tastes like you spent all afternoon. The potatoes get a little soft when frozen, so if I'm freezing a batch, I leave them out and boil a few fresh ones when I warm it up.""",
   "stew in freezer containers", "IT FREEZES BEAUTIFULLY")

ch("Grandma's kitchen")
sc("""So one more time. Buy a whole chuck roast and cut big chunks. Brown it in batches, and keep those brown bits. Cook the onion and tomato paste in the same pot. Never a hard boil, just a lazy bubble or a low oven. Put the vegetables in halfway. And finish it with a splash of vinegar and a handful of peas. That's beef stew the way my mother made it, and nobody's ever done it better.""",
   "beef stew on family table winter", "NOBODY DID IT BETTER")
sc("""Tell me in the comments, sweetheart. Biscuits, cornbread, or crusty bread with your stew? I want to know how your family eats it. The whole playlist of Grandma's recipes is right there on your screen, and I'll see you in the next video. Good night, honey.""",
   "kitchen table winter evening warm light", "BISCUITS OR BREAD?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma81", "Beef Stew EVERYONE's Grandma Made (Why Your Meat Is TOUGH)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Recipe as written by Grandma Ruth: 2 1/2 lb beef chuck in 2-inch chunks, flour, oil, onion, garlic, 2 tbsp tomato paste, 4 cups beef broth, bay leaf, thyme, potatoes, carrots, celery; gentle simmer or 325F oven about 2 1/2 hours; finished with 1 tbsp vinegar, peas and parsley."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
